import{z as A,x as B,o as s,c as p,q as n,j as E,D as r,d as t,s as o,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"可持久化线段树","description":"","frontmatter":{"title":"可持久化线段树","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/persistent-segment-tree.md","filePath":"cs/persistent-segment-tree.md","lastUpdated":1791063341000}'),d={name:"cs/persistent-segment-tree.md"};function m(u,a,c,D,h,f){const l=B("Mermaid");return s(),p("div",null,[a[2]||(a[2]=n('<h1 id="可持久化线段树" tabindex="-1">可持久化线段树 <a class="header-anchor" href="#可持久化线段树" aria-label="Permalink to &quot;可持久化线段树&quot;">​</a></h1><div class="epigraph"><p>每次修改只复制根到叶的 $O(\\log n)$ 个新节点，旧根仍指向未改的子树；版本是一条根指针。</p><footer>—— 据 Driscoll, Sarnak, Sleator and Tarjan, Making Data Structures Persistent, JCSS 1989；Okasaki, Purely Functional Data Structures 整理</footer></div><p><a href="/cs/segment-tree-lazy">上一课</a>让同一棵树在更新后丢掉旧聚合。若还要问「第 \\(k\\) 次修改之前 \\([l,r]\\) 的和」，就得把历史留下来。本课不重讲懒标记复合。缺口是可持久化（主席树常用形态）：路径复制，每版本 \\(O(\\log n)\\) 新节点。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>函数式与回溯、整体二分、区间第 \\(k\\) 小，都需要多份数组快照。整表复制每次 \\(\\Theta(n)\\)。缺口是：<strong>共享未改子树</strong>。修改 \\(A[i]\\)：新建叶与祖先，左右孩子指针能指旧节点的就指旧的。每个版本一个根。查询带着根走，语义与普通线段树相同，只是读的是那一版。</p><p><span class="marginnote">数字感受一下省了多少：\\(n=2^{20}\\) 时一条根到叶路径约 20 个节点；存 10 万个历史版本，路径复制约新建 200 万个节点，整表复制则要抄 1000 亿次——差五个数量级。</span></p><p><span class="marginnote">Driscoll et al. 区分部分/完全持久与函数式（只出新版本）。主席树是函数式线段树的竞赛名，本课用路径复制说话。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>建版本 \\(0\\) 与建普通树相同。从版本 \\(v\\) 改点 \\(i\\) 得版本 \\(v+1\\)：递归时若区间不含 \\(i\\) 则返回旧节点指针；含 \\(i\\) 则 <code>new</code> 一个节点，一边接递归结果，一边接旧孩子。空间对 \\(m\\) 次修改是 \\(O(n+m\\log n)\\)。查询 \\(O(\\log n)\\)，不写回。</p>',9)),(s(),E(i,null,{default:r(()=>[o(l,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20OLD%5B%22%E6%97%A7%E6%A0%B9%22%5D%20--%3E%20SHARE%5B%22%E6%9C%AA%E6%94%B9%E5%AD%90%E6%A0%91%E5%85%B1%E4%BA%AB%22%5D%0A%20%20NEW%5B%22%E6%96%B0%E6%A0%B9%22%5D%20--%3E%20PATH%5B%22O(log%20n)%20%E6%96%B0%E8%8A%82%E7%82%B9%22%5D%0A%20%20PATH%20--%3E%20SHARE%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"懒标记与可持久化可以同时做，但标记下传会被迫复制孩子，常数与正确性更烦；本课默认点修可持久化，不把懒标持久化写完。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"常见误区：一是以为每次更新要拷整棵树——其实只有根到叶那一小条；二是以为查询也会长出新节点——查询带根只读、一个节点都不新建，这也是它敢被并发读的原因。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,[t("旧根可达的节点永不原地改，否则历史被污染。这要求分配新节点，不能在数组线段树里覆写 \\(2u\\)。动态开点：若值域大、实际点少，节点按需 "),e("code",null,"new"),t("，同一套复制。区间第 \\(k\\) 小：权值线段树每个前缀一个版本，两点根相减得区间频次——那是应用，机制仍是版本差。")],-1)),(s(),E(i,null,{default:r(()=>[o(l,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20PA%5B%22%E5%89%8D%E7%BC%80%20r%20%E7%89%88%E6%9C%AC%E7%9A%84%E6%A0%B9%22%5D%20--%3E%20SUB%5B%22%E4%B8%A4%E6%A3%B5%E6%A0%91%E5%AF%B9%E5%BA%94%E8%8A%82%E7%82%B9%E9%80%90%E4%BD%8D%E7%9B%B8%E5%87%8F%22%5D%0A%20%20PB%5B%22%E5%89%8D%E7%BC%80%20l-1%20%E7%89%88%E6%9C%AC%E7%9A%84%E6%A0%B9%22%5D%20--%3E%20SUB%0A%20%20SUB%20--%3E%20F%5B%22%E5%BE%97%E5%88%B0%E5%8C%BA%E9%97%B4%20l..r%20%E5%86%85%E6%AF%8F%E4%B8%AA%E5%80%BC%E7%9A%84%E5%87%BA%E7%8E%B0%E6%AC%A1%E6%95%B0%22%5D%0A%20%20F%20--%3E%20WALK%5B%22%E7%9C%8B%E5%B7%A6%E5%AD%90%E6%A0%91%E8%AE%A1%E6%95%B0%E4%B8%8E%20k%20%E6%AF%94%E5%A4%A7%E5%B0%8F%E5%86%B3%E5%AE%9A%E5%BE%80%E5%93%AA%E8%B5%B0%22%5D%0A%20%20WALK%20--%3E%20K%5B%22%E8%90%BD%E5%88%B0%E5%8F%B6%E5%AD%90%E5%8D%B3%E7%AC%AC%20k%20%E5%B0%8F%E7%9A%84%E5%80%BC%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=n('<p>与后课<a href="/cs/persistent-path-copy">路径复制</a>同一思想，本课先在线段树上落地。</p><p><span class="marginnote">术语翻译：「权值线段树」是下标不是数组位置、而是值本身的线段树，叶子存「这个值出现过几次」。两个前缀版本一相减，恰好把多算的前缀抵掉，剩下的就是询问区间——这就是「版本差」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把并查集可持久化、或 fat node 的完全持久写进来。空间随版本线性涨，不能当无限日志。并发多写者抢同一版本链需要后课无锁/持久化另一套语言。</p><p>后课默认：要历史区间聚合，持有旧根。单次扫描上的近邻结构，用单调栈队列。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>可持久化线段树：改路径复制，\\(O(\\log n)\\) 新节点/版本。</li><li>旧根只读；原地写会毁掉历史。</li><li>下一缺口是线性扫描里的近邻，不是更多版本。</li><li>出处：Driscoll et al., <em>JCSS</em>, 1989；Okasaki。</li></ul>',7))])}const k=A(d,[["render",m]]);export{S as __pageData,k as default};
